console.log([] + []);       // '' — [].toString() is ''
console.log([] + {});       // '[object Object]'
console.log({} + []);       // 0 in some engines (statement vs expression)
console.log([1, 2] + 3);    // '1,23'

const obj = {
  valueOf() { return 99; },
  toString() { return 'custom'; }
};
console.log(obj + 1);       // 100 — valueOf wins for +
console.log(String(obj));   // 'custom' — String() prefers toString

